Тогда текущую схему не трогаете, а добавляете новую версию и шаг миграции:

```swift
enum BookSchemaV1: VersionedSchema {
    static var versionIdentifier = Schema.Version(1, 0, 0)
    static var models: [any PersistentModel.Type] { [Book.self] }

    @Model final class Book {          // как было, без изменений
        var title: String
        var author: String
        init(title: String, author: String) { self.title = title; self.author = author }
    }
}

enum BookSchemaV2: VersionedSchema {
    static var versionIdentifier = Schema.Version(2, 0, 0)
    static var models: [any PersistentModel.Type] { [Book.self] }

    @Model final class Book {
        var title: String
        var author: String
        var pageCount: Int?
        init(title: String, author: String, pageCount: Int? = nil) {
            self.title = title; self.author = author; self.pageCount = pageCount
        }
    }
}

typealias Book = BookSchemaV2.Book

enum BookMigrationPlan: SchemaMigrationPlan {
    static var schemas: [any VersionedSchema.Type] { [BookSchemaV1.self, BookSchemaV2.self] }
    static var stages: [MigrationStage] {
        [.lightweight(fromVersion: BookSchemaV1.self, toVersion: BookSchemaV2.self)]
    }
}
```

```swift
