## Минимальное изменение

```swift
@Model
final class Book {
    var title: String
    var author: String
    var pageCount: Int?          // новое поле

    init(title: String, author: String, pageCount: Int? = nil) {
        self.title = title
        self.author = author
        self.pageCount = pageCount
    }
}
```

Почему `Int?`, а не `Int`:
- **Миграция.** Добавить опциональное поле — самый надёжный вариант lightweight-миграции: у старых записей будет `nil`. Если делать `Int`, обязательно нужно значение по умолчанию (`var pageCount: Int = 0`). Без него автоматическая миграция не пройдёт.
- **Смысл.** `nil` значит «не указано», а `0` выглядит как настоящее значение.
- **CloudKit.** Если синхронизация включена сейчас или появится позже, CloudKit всё равно требует, чтобы поля были опциональными или со значением по умолчанию.

Чего не делать в этом же релизе: переименовывать или удалять старые поля, менять их типы и добавлять `@Attribute(.unique)`. Такие изменения уже не проходят как lightweight.

## Лучше: сразу перейти на версионированную схему

Если `VersionedSchema` у вас ещё нет, сейчас удобный момент её ввести. Тогда все будущие изменения модели будут контролируемыми:

```swift
enum BookSchemaV1: VersionedSchema {
    static let versionIdentifier = Schema.Version(1, 0, 0)
    static var models: [any PersistentModel.Type] { [Book.self] }

    // Модель должна В ТОЧНОСТИ совпадать с той, что в сборке у тестировщиков
    @Model
    final class Book {
        var title: String
        var author: String

        init(title: String, author: String) {
            self.title = title
            self.author = author
        }
    }
}

enum BookSchemaV2: VersionedSchema {
    static let versionIdentifier = Schema.Version(2, 0, 0)
    static var models: [any PersistentModel.Type] { [Book.self] }

    @Model
    final class Book {
        var title: String
        var author: String
        var pageCount: Int?

        init(title: String, author: String, pageCount: Int? = nil) {
            self.title = title
            self.author = author
            self.pageCount = pageCount
        }
    }
}

enum BookMigrationPlan: SchemaMigrationPlan {
    static var schemas: [any VersionedSchema.Type] {
        [BookSchemaV1.self, BookSchemaV2.self]
    }
    static var stages: [MigrationStage] {
        [.lightweight(fromVersion: BookSchemaV1.self, toVersion: BookSchemaV2.self)]
    }
}

// Чтобы остальной код не пришлось трогать
typealias Book = BookSchemaV2.Book
```

Создание контейнера (в `App` или там, где он у вас создаётся):

```swift
let container = try ModelContainer(
    for: Book.self,
    migrationPlan: BookMigrationPlan.self
)
```

Если сейчас используется `.modelContainer(for: Book.self)`, замените его на `.modelContainer(container)` с контейнером, созданным как выше.

